#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser when on a local GUI desktop;
# over SSH / headless servers it prints the URL cleanly without blocking.
open_url() {
  local url="$1"
  if [[ -n "${SSH_CONNECTION:-}${SSH_CLIENT:-}${SSH_TTY:-}" ]]; then
    printf '  %s↗ Open on your device:%s %s\n' "$GREEN" "$RESET" "$url"
    return 0
  fi
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url" </dev/null
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url" </dev/null
    elif [[ -n "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ]] && command -v xdg-open >/dev/null 2>&1; then xdg-open "$url" </dev/null
    elif [[ "$(uname -s)" == "Darwin" ]] && command -v open >/dev/null 2>&1; then open "$url" </dev/null
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser locally — open on your device: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
  local repo_root existing_lan_ip existing_owner_token bot_me_json bot_username bot_user_id
  local user_install_url bot_dm_url
  LAN_HOST_IP=""
  OWNER_API_BEARER_TOKEN=""
  DISCORD_APPLICATION_ID=""
  DISCORD_BOT_TOKEN=""
  DISCORD_OWNER_USER_ID=""

  repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
  [[ -f .env.example || ! -f "$repo_root/.env.example" ]] || cd "$repo_root"

  TOTAL_STAGES=5

  banner "Voice Clone Pipeline · 1-on-1 Discord Bot Setup"

  # ── Stage 1: LAN Host IP, Local API & Database Credentials ───────────────
  stage "LAN Host IP, Local API & Database Credentials"
  say "Ensuring $ENV_FILE starts from .env.example and configuring LAN_HOST_IP + OWNER_API_BEARER_TOKEN."
  if [[ ! -f "$ENV_FILE" ]]; then
    [[ -f "$ENV_FILE" ]] || cp .env.example "$ENV_FILE"
    note "Created $ENV_FILE from .env.example."
  else
    note "Using existing $ENV_FILE."
  fi

  existing_lan_ip=$(_existing LAN_HOST_IP || true)
  say "Nginx auto-generates a persisted SAN TLS certificate on :3443 for LAN browser microphone capture."
  ask LAN_HOST_IP "Server LAN IP for HTTPS Studio Mic & API (default ${existing_lan_ip:-127.0.0.1}):"
  LAN_HOST_IP="${LAN_HOST_IP//[[:space:]]/}"
  [[ -n "$LAN_HOST_IP" ]] || LAN_HOST_IP="${existing_lan_ip:-127.0.0.1}"
  write_env LAN_HOST_IP "$LAN_HOST_IP"

  existing_owner_token=$(_existing OWNER_API_BEARER_TOKEN || true)
  if [[ -z "$existing_owner_token" || "$existing_owner_token" == replace-with-* ]]; then
    if command -v openssl >/dev/null 2>&1; then
      OWNER_API_BEARER_TOKEN=$(openssl rand -hex 32)
    else
      OWNER_API_BEARER_TOKEN=$(od -An -N32 -tx1 /dev/urandom | tr -d ' \n')
    fi
    say "Generated a fresh 32-byte hex OWNER_API_BEARER_TOKEN for your local API & Studio UI."
  else
    OWNER_API_BEARER_TOKEN="$existing_owner_token"
    say "Found an existing OWNER_API_BEARER_TOKEN in $ENV_FILE."
  fi

  if confirm "Override OWNER_API_BEARER_TOKEN with a custom secret instead of keeping this one?"; then
    while true; do
      ask_secret OWNER_API_BEARER_TOKEN "Paste custom OWNER_API_BEARER_TOKEN:"
      if [[ -z "$OWNER_API_BEARER_TOKEN" || "$OWNER_API_BEARER_TOKEN" == replace-with-* ]]; then
        warn "OWNER_API_BEARER_TOKEN cannot be empty or the .env.example placeholder."
        continue
      fi
      break
    done
  fi
  write_env OWNER_API_BEARER_TOKEN "$OWNER_API_BEARER_TOKEN"
  pause "Press Enter to continue to Stage 2"

  # ── Stage 2: Discord Developer Portal: Create Application ────────────────
  stage "Discord Developer Portal: Create Application"
  say "Create a personal Discord Application to host your slash commands & 1-on-1 bot."
  open_url "https://discord.com/developers/applications"
  step "Click 'New Application' (top-right), name it (e.g. \"My Voice Clone\"), and click Create."
  step "Open 'General Information' in the left sidebar."
  step "Copy the 'Application ID' (17–20 digit snowflake)."
  while true; do
    ask DISCORD_APPLICATION_ID "Paste your Discord Application ID:"
    DISCORD_APPLICATION_ID="${DISCORD_APPLICATION_ID//[[:space:]]/}"
    if [[ ! "$DISCORD_APPLICATION_ID" =~ ^[0-9]{17,20}$ ]]; then
      warn "Application ID must be a 17–20 digit snowflake (digits only)."
      continue
    fi
    if [[ "$DISCORD_APPLICATION_ID" == "123456789012345678" ]]; then
      warn "123456789012345678 is the .env.example placeholder—copy your real Application ID."
      confirm "Keep 123456789012345678 anyway?" || continue
    fi
    break
  done
  write_env DISCORD_APPLICATION_ID "$DISCORD_APPLICATION_ID"
  pause "Press Enter to continue to Stage 3"

  # ── Stage 3: Enable User Install & Bot Contexts ──────────────────────────
  stage "Enable User Install & Bot Contexts"
  say "Configure Installation Contexts so /voice_clone works in all DMs & servers AND as a 1-on-1 bot."
  open_url "https://discord.com/developers/applications/${DISCORD_APPLICATION_ID}/installation"
  step "Under 'Installation Contexts', check BOTH 'User Install' AND 'Guild Install'."
  step "Set 'Install Link' to 'Discord Provided Link'."
  step "Under 'Default Install Settings' → 'User Install', add scope: applications.commands"
  step "Under 'Default Install Settings' → 'Guild Install', add scopes: applications.commands and bot"
  step "Click 'Save Changes' at the bottom of the page."
  pause "Press Enter once Installation settings are saved"

  # ── Stage 4: Create Bot User & Capture Bot Token ─────────────────────────
  stage "Create Bot User & Capture Bot Token"
  say "Reset and capture your Discord Bot Token, then verify it live against Discord API v10."
  open_url "https://discord.com/developers/applications/${DISCORD_APPLICATION_ID}/bot"
  step "Click 'Reset Token' (confirm in the modal / 2FA prompt if asked)."
  step "Copy the newly revealed Bot Token to your clipboard."
  while true; do
    ask_secret DISCORD_BOT_TOKEN "Paste your Discord Bot Token:"
    DISCORD_BOT_TOKEN="${DISCORD_BOT_TOKEN//[[:space:]]/}"
    if [[ -z "$DISCORD_BOT_TOKEN" || "$DISCORD_BOT_TOKEN" == replace-with-* ]]; then
      warn "Bot Token cannot be empty or the .env.example placeholder."
      continue
    fi
    bot_me_json=""
    if bot_me_json=$(curl -fsS -H "Authorization: Bot $DISCORD_BOT_TOKEN" "https://discord.com/api/v10/users/@me" 2>/dev/null); then
      bot_username=$(printf '%s' "$bot_me_json" | sed -n 's/.*"username"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n1)
      bot_user_id=$(printf '%s' "$bot_me_json" | sed -n 's/.*"id"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n1)
      printf '  %s✓ Verified Discord Bot: @%s (id: %s)%s\n' \
        "$GREEN" "${bot_username:-verified-bot}" "${bot_user_id:-ok}" "$RESET"
      break
    else
      warn "Live check against https://discord.com/api/v10/users/@me failed (invalid token or offline)."
      if confirm "Save this DISCORD_BOT_TOKEN anyway?"; then
        break
      fi
    fi
  done
  write_env DISCORD_BOT_TOKEN "$DISCORD_BOT_TOKEN"
  pause "Press Enter to continue to Stage 5"

  # ── Stage 5: Owner Lock & Open Your 1-on-1 Bot Chat ──────────────────────
  stage "Owner Lock & Open Your 1-on-1 Bot Chat"
  say "Lock your bot to your personal Discord User ID, then authorize both OAuth install links."
  step "In Discord, open Settings (⚙) → Advanced → enable 'Developer Mode'."
  step "Right-click your own avatar anywhere in Discord and click 'Copy User ID'."
  while true; do
    ask DISCORD_OWNER_USER_ID "Paste your personal Discord User ID:"
    DISCORD_OWNER_USER_ID="${DISCORD_OWNER_USER_ID//[[:space:]]/}"
    if [[ ! "$DISCORD_OWNER_USER_ID" =~ ^[0-9]{17,20}$ ]]; then
      warn "Discord User ID must be a 17–20 digit snowflake (digits only)."
      continue
    fi
    if [[ "$DISCORD_OWNER_USER_ID" == "987654321098765432" ]]; then
      warn "987654321098765432 is the .env.example placeholder—copy your real User ID."
      confirm "Keep 987654321098765432 anyway?" || continue
    fi
    break
  done
  write_env DISCORD_OWNER_USER_ID "$DISCORD_OWNER_USER_ID"

  user_install_url="https://discord.com/oauth2/authorize?client_id=${DISCORD_APPLICATION_ID}&integration_type=1&scope=applications.commands"
  bot_dm_url="https://discord.com/oauth2/authorize?client_id=${DISCORD_APPLICATION_ID}&integration_type=0&scope=bot+applications.commands&permissions=274877910016"

  printf '\n'
  say "1) Personal Account Install (USER_INSTALL — enables /voice_clone in every DM & server):"
  open_url "$user_install_url"
  pause "Authorize Personal Account Install in your browser, then press Enter for Link 2"

  printf '\n'
  say "2) Server / 1-on-1 Bot DM Link (creates the 1-on-1 DM channel with your bot):"
  open_url "$bot_dm_url"
  pause "Authorize the bot in a personal server to open your 1-on-1 Bot DM, then press Enter to finish"

  finish

  say "Start the stack and chat 1-on-1 with your cloned voice bot:"
  step "Boot stack:     make up   (Windows Browser Mic UI: http://localhost:3000 · LAN HTTPS UI: https://${LAN_HOST_IP}:3443)"
  step "Enroll voice:   Open http://localhost:3000 in Chrome/Edge on Windows → '2. Voice Recording & Enrollment Studio'"
  step "Chat 1-on-1:    Use /speak, /voice_clone, /voice_settings, /voice_profiles, or DM 'es: Hey there!'"
  printf '\n'
  note "OAuth Quick-Launch URLs (also clickable in Studio UI → Tab 5):"
  note "  1) USER_INSTALL:  $user_install_url"
  note "  2) 1-on-1 Bot DM: $bot_dm_url"
  printf '\n'

  if [[ -d "./local_storage" ]]; then
    ENV_FILE="./local_storage/studio.env"
    write_env DISCORD_APPLICATION_ID "$DISCORD_APPLICATION_ID" >/dev/null
    write_env DISCORD_BOT_TOKEN "$DISCORD_BOT_TOKEN" >/dev/null
    write_env DISCORD_OWNER_USER_ID "$DISCORD_OWNER_USER_ID" >/dev/null
  fi
}

if [[ "${1:-}" == "--app-id" || "${1:-}" == "--non-interactive" || "${1:-}" == "--help" || "${1:-}" == "-h" ]]; then
  APP_ID=""
  BOT_TOKEN=""
  OWNER_ID=""
  JSON_OUT=false
  SKIP_VERIFY=false
  while [[ $# -gt 0 ]]; do
    case "$1" in
      --non-interactive) shift ;;
      --app-id) APP_ID="$2"; shift 2 ;;
      --bot-token) BOT_TOKEN="$2"; shift 2 ;;
      --owner-id) OWNER_ID="$2"; shift 2 ;;
      --env-file) ENV_FILE="$2"; shift 2 ;;
      --skip-verify) SKIP_VERIFY=true; shift ;;
      --json) JSON_OUT=true; shift ;;
      -h|--help)
        echo "Usage: ./scripts/setup-discord.sh [--app-id <id> --bot-token <tok> --owner-id <id> [--env-file .env] [--skip-verify] [--json]]"
        exit 0
        ;;
      *) echo "Unknown argument: $1" >&2; exit 2 ;;
    esac
  done
  [[ "$APP_ID" =~ ^[0-9]{17,20}$ ]] || { echo "Invalid --app-id (expected 17-20 digit snowflake)" >&2; exit 2; }
  [[ "$OWNER_ID" =~ ^[0-9]{17,20}$ ]] || { echo "Invalid --owner-id (expected 17-20 digit snowflake)" >&2; exit 2; }
  [[ -n "$BOT_TOKEN" && "$BOT_TOKEN" != replace-with-* ]] || { echo "Invalid --bot-token" >&2; exit 2; }
  VERIFIED_USER=""
  if [[ "$SKIP_VERIFY" == "false" ]]; then
    me_json="$(curl -fsS -H "Authorization: Bot $BOT_TOKEN" "https://discord.com/api/v10/users/@me")"
    VERIFIED_USER="$(printf '%s' "$me_json" | sed -n 's/.*"username"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n1)"
  fi
  write_env DISCORD_APPLICATION_ID "$APP_ID" >/dev/null
  write_env DISCORD_BOT_TOKEN "$BOT_TOKEN" >/dev/null
  write_env DISCORD_OWNER_USER_ID "$OWNER_ID" >/dev/null
  if [[ -d "./local_storage" ]]; then
    ENV_FILE="./local_storage/studio.env"
    write_env DISCORD_APPLICATION_ID "$APP_ID" >/dev/null
    write_env DISCORD_BOT_TOKEN "$BOT_TOKEN" >/dev/null
    write_env DISCORD_OWNER_USER_ID "$OWNER_ID" >/dev/null
  fi
  u_url="https://discord.com/oauth2/authorize?client_id=${APP_ID}&integration_type=1&scope=applications.commands"
  b_url="https://discord.com/oauth2/authorize?client_id=${APP_ID}&integration_type=0&scope=bot+applications.commands&permissions=274877910016"
  if [[ "$JSON_OUT" == "true" ]]; then
    printf '{"saved":true,"verified_bot_username":"%s","user_install_url":"%s","bot_dm_url":"%s"}\n' "$VERIFIED_USER" "$u_url" "$b_url"
  else
    printf 'Saved Discord credentials (@%s).\n  USER_INSTALL: %s\n  BOT_DM:       %s\n' "${VERIFIED_USER:-bot}" "$u_url" "$b_url"
  fi
  exit 0
fi

run_wizard "$@"; exit
